package varargs.metidos.objetos.orientacao.domain;public class Calculator {    public void somaNums(int[] numeros){        int soma = 0;        for (int s : numeros){            soma += s;        }    }    public void subNums (int[] subtrair){        int subt = 0;        for (int sub : subtrair){           subt -= sub;        }    }    public void multiplyNums (int[] multiply){        int multi = 0;        for (int mult : multiply){            multi *= mult;        }    }    public void divNums (int[] dividir){        int div = 0;        for (int dvd : dividir){            div /= dvd;        }    }    public int somaArraysVarArgs(int[] numeros){        int soma = 0;        for (int s : numeros){            soma += s;        }        return soma;    }}